                for (int j = 0; j < other.cols; j++) {
                    for (int k = 0; k < cols; k++) {
                        result.data[i][j] += data[i][k] * other.data[k][j];
                    }
                }
            }
            return result;
        } else {
            std::cerr << "Matrices cannot be multiplied due to incompatible dimensions." << std::endl;
            return Matrix(0, 0);
        }
    }

    // Function to print the matrix
    void print() const {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                std::cout << data[i][j] << " ";
            }
            std::cout << std::endl;
        }
    }
};

